export async function getVpcId(vpcName: string): Promise<string> {
  const params = {
    Filters: [
      {
        Name: "tag:Name",
        Values: [vpcName],
      },
    ],
  };
  const command = new DescribeVpcsCommand(params);
  const vpcId = (await client.send(command)).Vpcs?.[0].VpcId;
  return vpcId!;
}
export async function getSubnetIds(
  vpcId: string,
  subnets: string[]
): Promise<string[]> {
  const params = {
    Filters: [
      {
        Name: "vpc-id",
        Values: [vpcId],
      },
      {
        Name: "tag:Name",
        Values: subnets,
      },
    ],
  };

  const command = new DescribeSubnetsCommand(params);
  const response = await client.send(command);
  const subnetsResponse = response.Subnets;

  const subnetIds = subnetsResponse
    ?.map((subnet) => subnet.SubnetId)
    .filter((id): id is string => id !== undefined);

  return subnetIds || [];
}

